 $apiEnd=$end->format('H:i:s')==='23:00:00'?$end:$end->modify('+1 day');
 $q=http_build_query(['latitude'=>implode(',',array_map(fn($x)=>sprintf('%.5f',$x),$lats)),'longitude'=>implode(',',array_map(fn($x)=>sprintf('%.5f',$x),$lons)),'hourly'=>implode(',',$vars),'start_date'=>$start->format('Y-m-d'),'end_date'=>$apiEnd->format('Y-m-d'),'timezone'=>'UTC','wind_speed_unit'=>'ms']);
 $ch=curl_init(OPEN_METEO.'?'.$q);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>90,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_USERAGENT=>'Weter-Timeweb/2.0']);$body=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$code!==200)throw new RuntimeException('Open-Meteo HTTP '.$code.($err?': '.$err:''));$data=json_decode($body,true);if(!is_array($data))throw new RuntimeException('Некорректный ответ Open-Meteo');if(isset($data['hourly']))$data=[$data];return['lats'=>$lats,'lons'=>$lons,'cells'=>$data];
}
function timeIndex(array $times,DateTimeImmutable $target):array{$t=$target->getTimestamp();$n=count($times)-1;if($n<0)throw new RuntimeException('Пустой прогноз');$first=utc((string)$times[0])->getTimestamp();$last=utc((string)$times[$n])->getTimestamp();if($t<$first||$t>$last)throw new RuntimeException('Время '.iso($target).' выходит за границы прогноза.');if($t===$last)return[$n,$n,0.0];$lo=0;$hi=$n;while($lo<$hi){$m=intdiv($lo+$hi,2);if(utc((string)$times[$m])->getTimestamp()<$t)$lo=$m+1;else$hi=$m;}$i1=$lo;$i0=$i1-1;$a=utc((string)$times[$i0])->getTimestamp();$b=utc((string)$times[$i1])->getTimestamp();return[$i0,$i1,($t-$a)/max(1,$b-$a)];}
function cellWind(array $cell,float $alt,DateTimeImmutable $when):array{$h=$cell['hourly']??[];if(!isset($h['time']))throw new RuntimeException('Нет временного ряда Open-Meteo');[$i0,$i1,$f]=timeIndex($h['time'],$when);$v=[];foreach(LEVELS as $p){$k="{$p}hPa";$ss="wind_speed_$k";$dd="wind_direction_$k";$zz="geopotential_height_$k";if(!isset($h[$ss][$i0],$h[$ss][$i1],$h[$dd][$i0],$h[$dd][$i1],$h[$zz][$i0],$h[$zz][$i1]))continue;$s0=(float)$h[$ss][$i0];$s1=(float)$h[$ss][$i1];$d0=(float)$h[$dd][$i0];$d1=(float)$h[$dd][$i1];$z0=(float)$h[$zz][$i0];$z1=(float)$h[$zz][$i1];[$e0,$n0]=winduv($s0,$d0);[$e1,$n1]=winduv($s1,$d1);$v[]=[$z0+($z1-$z0)*$f,$e0+($e1-$e0)*$f,$n0+($n1-$n0)*$f];}if(!$v)throw new RuntimeException('Для выбранного времени нет данных ветра.');usort($v,fn($a,$b)=>$a[0]<=>$b[0]);if($alt<=$v[0][0])return uvwind($v[0][1],$v[0][2]);$last=count($v)-1;if($alt>=$v[$last][0])return uvwind($v[$last][1],$v[$last][2]);for($i=1;$i<count($v);$i++){if($alt<=$v[$i][0]){$f2=($alt-$v[$i-1][0])/max(.001,$v[$i][0]-$v[$i-1][0]);return uvwind($v[$i-1][1]+($v[$i][1]-$v[$i-1][1])*$f2,$v[$i-1][2]+($v[$i][2]-$v[$i-1][2])*$f2);}}return uvwind($v[$last][1],$v[$last][2]);}
function nearestCell(array $fc,float $lat,float $lon):array{$best=null;$bd=INF;foreach($fc['cells'] as $c){$d=((float)($c['latitude']??0)-$lat)**2+((float)($c['longitude']??0)-$lon)**2;if($d<$bd){$bd=$d;$best=$c;}}if(!$best)throw new RuntimeException('Не найдена метеоячейка.');return$best;}
function interp(array $fc,float $lat,float $lon,float $alt,DateTimeImmutable $when):array{$ls=$fc['lats'];$os=$fc['lons'];sort($ls);sort($os);if($lat<$ls[0]||$lat>$ls[count($ls)-1]||$lon<$os[0]||$lon>$os[count($os)-1])throw new RuntimeException('Траектория вышла за пределы метеосетки.');$bounds=function(array $a,float $x):array{$n=count($a);if($x<=$a[0])return[$a[0],$a[0],0.0];if($x>=$a[$n-1])return[$a[$n-1],$a[$n-1],0.0];for($i=1;$i<$n;$i++)if($x<=$a[$i])return[$a[$i-1],$a[$i],($x-$a[$i-1])/($a[$i]-$a[$i-1])];return[$a[$n-1],$a[$n-1],0.0];};[$a,$b,$fy]=$bounds($ls,$lat);[$c,$d,$fx]=$bounds($os,$lon);$w=[];foreach([[$a,$c],[$a,$d],[$b,$c],[$b,$d]] as $p)$w[]=cellWind(nearestCell($fc,$p[0],$p[1]),$alt,$when);$uv=array_map(fn($x)=>winduv($x[0],$x[1]),$w);$e0=$uv[0][0]+($uv[1][0]-$uv[0][0])*$fx;$e1=$uv[2][0]+($uv[3][0]-$uv[2][0])*$fx;$n0=$uv[0][1]+($uv[1][1]-$uv[0][1])*$fx;$n1=$uv[2][1]+($uv[3][1]-$uv[2][1])*$fx;return uvwind($e0+($e1-$e0)*$fy,$n0+($n1-$n0)*$fy);}
function rk4Step(array $state,float $dt,DateTimeImmutable $t,array $fc,float $verticalSign,float $ascent,float $maxAlt):array{$der=function(float $la,float $lo,float $z,DateTimeImmutable $tm)use($fc,$verticalSign,$ascent,$maxAlt):array{$w=interp($fc,$la,$lo,$z,$tm);[$e,$n]=winduv($w[0],$w[1]);$vz=$verticalSign*($z<$maxAlt?$ascent:0);return[$e,$n,$vz];};[$k1e,$k1n,$k1z]=$der($state[0],$state[1],$state[2],$t);[$la2,$lo2]=destination($state[0],$state[1],$k1e*$dt/2,$k1n*$dt/2);$k2=$der($la2,$lo2,max(0,$state[2]+$k1z*$dt/2),$t->modify((string)round($dt/2).' seconds'));[$la3,$lo3]=destination($state[0],$state[1],$k2[0]*$dt/2,$k2[1]*$dt/2);$k3=$der($la3,$lo3,max(0,$state[2]+$k2[2]*$dt/2),$t->modify((string)round($dt/2).' seconds'));[$la4,$lo4]=destination($state[0],$state[1],$k3[0]*$dt,$k3[1]*$dt);$k4=$der($la4,$lo4,max(0,$state[2]+$k3[2]*$dt),$t->modify((string)round($dt).' seconds'));[$lat,$lon]=destination($state[0],$state[1],$dt*($k1e+2*$k2[0]+2*$k3[0]+$k4[0])/6,$dt*($k1n+2*$k2[1]+2*$k3[1]+$k4[1])/6);$z=max(0,$state[2]+$dt*($k1z+2*$k2[2]+2*$k3[2]+$k4[2])/6);return[$lat,$lon,$z];}
function traj(array $p,array $fc):array{$state=[(float)$p['lat'],(float)$p['lon'],max(0,(float)($p['start_altitude']??0))];$as=max(0,(float)($p['ascent_rate']??5));$max=max($state[2],(float)($p['max_altitude']??10000));$hours=min(168,max(.01,(float)($p['duration_hours']??24)));$step=max(1,(float)($p['step_minutes']??5))*60;$t=utc((string)$p['start_time']);$total=$hours*3600;$out=[];for($elapsed=0;$elapsed<=$total+1e-6;$elapsed+=$step){$out[]=['time'=>iso($t),'lat'=>$state[0],'lon'=>$state[1],'altitude'=>$state[2]];if($elapsed>=$total)break;$dt=min($step,$total-$elapsed);$state=rk4Step($state,$dt,$t,$fc,1,$as,$max);$t=$t->modify((string)round($dt).' seconds');}return$out;}
function backSolve(array $fc,float $dlat,float $dlon,float $alt,DateTimeImmutable $dt,float $hours,float $step,float $startAlt,float $ascent,float $biasE=0,float $biasN=0):array{$step=max(1,abs($step))*60;$hours=min(48,max(.01,$hours));$state=[$dlat,$dlon,max($startAlt,$alt)];$t=$dt;$remaining=$hours*3600;$out=[];$wind=function(float $la,float $lo,float $z,DateTimeImmutable $tm)use($fc,$biasE,$biasN):array{$w=interp($fc,$la,$lo,$z,$tm);[$e,$n]=winduv($w[0],$w[1]);return[$e+$biasE*(.65+.35*clamp($z/10000,0,1)),$n+$biasN*(.65+.35*clamp($z/10000,0,1))];};$out[]=['time'=>iso($t),'lat'=>$state[0],'lon'=>$state[1],'altitude'=>$state[2]];while($remaining>1e-6&&$state[2]>$startAlt){$h=min($step,$remaining);$der=function(float $la,float $lo,float $z,DateTimeImmutable $tm)use($wind,$ascent):array{[$e,$n]=$wind($la,$lo,$z,$tm);return[$e,$n,$ascent];};[$e1,$n1,$z1]=$der($state[0],$state[1],$state[2],$t);[$la2,$lo2]=destination($state[0],$state[1],-$e1*$h/2,-$n1*$h/2);$z2=max($startAlt,$state[2]-$z1*$h/2);[$e2,$n2,$z2v]=$der($la2,$lo2,$z2,$t->modify('-'.(int)round($h/2).' seconds'));[$la3,$lo3]=destination($state[0],$state[1],-$e2*$h/2,-$n2*$h/2);$z3=max($startAlt,$state[2]-$z2v*$h/2);[$e3,$n3,$z3v]=$der($la3,$lo3,$z3,$t->modify('-'.(int)round($h/2).' seconds'));[$la4,$lo4]=destination($state[0],$state[1],-$e3*$h,-$n3*$h);$z4=max($startAlt,$state[2]-$z3v*$h);[$e4,$n4,$z4v]=$der($la4,$lo4,$z4,$t->modify('-'.(int)round($h).' seconds'));[$lat,$lon]=destination($state[0],$state[1],-$h*($e1+2*$e2+2*$e3+$e4)/6,-$h*($n1+2*$n2+2*$n3+$n4)/6);$state=[$lat,$lon,max($startAlt,$state[2]-$h*($z1+2*$z2v+2*$z3v+$z4v)/6)];$t=$t->modify('-'.(int)round($h).' seconds');$remaining-=$h;$out[]=['time'=>iso($t),'lat'=>$state[0],'lon'=>$state[1],'altitude'=>$state[2]];}return$out;}
function backEnsemble(array $fc,float $dlat,float $dlon,float $alt,DateTimeImmutable $dt,float $hours,float $step,float $ascent,int $members,float $windSigma=1.5,float $timeSigma=60,float $altSigma=50):array{mt_srand(42);$trajectories=[];$launches=[];for($i=0;$i<$members;$i++){try{$tt=$dt->modify((string)round(gaussian()*$timeSigma).' seconds');$zz=max(0,$alt+gaussian()*$altSigma);$aa=max(.2,$ascent+gaussian()*.7);$tr=backSolve($fc,$dlat,$dlon,$zz,$tt,$hours,$step,0,$aa,gaussian()*$windSigma,gaussian()*$windSigma);if($tr){$trajectories[]=$tr;$launches[]=$tr[count($tr)-1];}}catch(Throwable){}}mt_srand();if(!$launches)throw new RuntimeException('Не удалось построить обратные траектории.');$clat=array_sum(array_column($launches,'lat'))/count($launches);$clon=array_sum(array_column($launches,'lon'))/count($launches);$dist=[];foreach($launches as $q)$dist[]=hav($clat,$clon,$q['lat'],$q['lon']);$sorted=$dist;sort($sorted);$n=count($sorted);$zones=[];foreach([.5,.8,.95] as $q){$idx=min($n-1,(int)floor($q*($n-1)));$zones[]=['probability'=>$q,'radius_m'=>$sorted[$idx],'center_lat'=>$clat,'center_lon'=>$clon];}$best=array_keys($dist,min($dist))[0];return['trajectories'=>$trajectories,'launch_estimate'=>$launches[$best],'zones'=>$zones,'valid_members'=>$n,'ensemble_size'=>$members];}
